//! Passive gauge cloning and main-document import preserve actual metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=pl for=progress>Work</label><progress id=progress max=10 value=2>Before <span>progress</span></progress><meter id=meter min=-10 max=30 value=20 low=0 high=25 optimum=10>Before <b>meter</b></meter><input id=neighbor value=seed></form><div id=target></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://gauge-lifecycle.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn gauge_lifecycle_native_shallow_deep_clones_have_independent_actual_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var key of ['progress','meter']){var x=document.getElementById(key),C=key==='progress'?HTMLProgressElement:HTMLMeterElement,deep=x.cloneNode(true),shallow=x.cloneNode(false),a=x.getAttributeNode('value'),b=deep.getAttributeNode('value');if(deep===x||!(deep instanceof C)||deep.ownerDocument!==document||deep.parentNode!==null||deep.value!==x.value||deep.max!==x.max||deep.textContent!==x.textContent||deep.firstChild===x.firstChild||shallow.textContent!==''||shallow.value!==x.value||b===a)throw 'genuine gauge clone';deep.value=7;if(b.value!=='7'||a.value==b.value||x.getAttributeNode('value')!==a)throw 'independent clone attributes';}if(document.getElementById('owner').length!==1||document.getElementById('neighbor').value!=='seed')throw 'gauge clones are not native form controls';"#);}
#[test]
fn gauge_lifecycle_inert_import_retains_exact_attributes_and_native_interfaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml';for(var key of ['progress','meter']){var x=doc.createElementNS(html,key),C=key==='progress'?HTMLProgressElement:HTMLMeterElement;x.setAttribute('value','3\ud800tail');x.max=10;x.appendChild(doc.createTextNode('Fallback\ud800'));var source=x.getAttributeNode('value'),copy=document.importNode(x,true),a=copy.getAttributeNode('value');if(!(copy instanceof C)||copy.ownerDocument!==document||copy.parentNode!==null||copy.value!==3||copy.max!==10||copy.textContent!=='Fallback\ud800'||a.value!=='3\ud800tail'||a===source||source.ownerElement!==x)throw 'exact imported gauge';document.getElementById('target').appendChild(copy);copy.value=4;if(copy.value!==4||x.value!==3||source.value!=='3\ud800tail'||a.value!=='4')throw 'independent connected imported gauge';}"#);}
#[test]
fn gauge_lifecycle_dynamic_native_promotion_keeps_identity_labels_and_fallback_children(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var target=document.getElementById('target');for(var key of ['progress','meter']){var x=document.createElement(key),C=key==='progress'?HTMLProgressElement:HTMLMeterElement;x.id='dynamic-'+key;x.max=10;x.value=5;x.appendChild(document.createTextNode('Dynamic fallback'));var a=x.getAttributeNode('value'),labels=x.labels,watch=new MutationObserver(function(){});watch.observe(target,{childList:true});var inserted=target.appendChild(x),records=watch.takeRecords();if(inserted!==x||!(x instanceof C)||x.ownerDocument!==document||x.parentNode!==target||x.value!==5||x.textContent!=='Dynamic fallback'||x.getAttributeNode('value')!==a||a.ownerElement!==x||x.labels!==labels||records.length!==1||records[0].addedNodes[0]!==x)throw 'actual native gauge promotion';x.textContent='Changed fallback';if(x.textContent!=='Changed fallback'||x.value!==5)throw 'fallback replacement independent of numeric metadata';watch.disconnect();}if(document.getElementById('owner').length!==1)throw 'gauges are not listed controls';"#);}

// Gauge copies and connection use the shared ordinary-element transaction.
#[test]
fn gauge_lifecycle_exact_native_attributes_and_fallback_replacement_keep_numeric_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var target=document.getElementById('target');for(var key of ['progress','meter']){var x=document.getElementById(key);x.setAttribute('value','3\ud800tail');var source=x.getAttributeNode('value'),copy=x.cloneNode(true),attr=copy.getAttributeNode('value');copy.id='copied-'+key;target.appendChild(copy);if(copy.value!==3||attr.value!=='3\ud800tail'||attr.ownerElement!==copy||source.ownerElement!==x||source===attr)throw 'exact cloned gauge attributes';var first=copy.firstChild,children=copy.childNodes,watch=new MutationObserver(function(){});watch.observe(copy,{childList:true,subtree:true});copy.textContent='New\ud800fallback';var records=watch.takeRecords();if(copy.value!==3||copy.textContent!=='New\ud800fallback'||copy.childNodes!==children||children.length!==1||first.parentNode!==null||records.length!==1||records[0].removedNodes[0]!==first||x.textContent===copy.textContent||copy.getAttributeNode('value')!==attr)throw 'actual fallback replacement';watch.disconnect();}if(document.getElementById('neighbor').value!=='seed')throw 'neighbor state';"#);
}
#[test]
fn gauge_lifecycle_shallow_import_and_template_parking_use_actual_metadata(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',target=document.getElementById('target');for(var key of ['progress','meter']){var source=doc.createElementNS(html,key);source.max=20;source.value=5;source.appendChild(doc.createTextNode('Fallback'));var copy=document.importNode(source,false);if(copy.value!==5||copy.max!==20||copy.textContent!==''||source.textContent!=='Fallback')throw 'shallow gauge import';var template=document.createElement('template'),leaf=copy.cloneNode(false);template.content.appendChild(leaf);if(template.content.firstChild!==leaf||leaf.value!==5||leaf.ownerDocument!==template.content.ownerDocument)throw 'parked gauge metadata';target.appendChild(template);if(leaf.parentNode!==template.content||leaf.value!==5||template.content.firstChild!==leaf)throw 'parked gauge survives template connection';}"#);
}
#[test]
fn gauge_lifecycle_clone_import_and_promotion_preserve_active_content_guards(){
 for tag in ["progress","meter"]{for operation in ["clone","import","promote"]{
  let(mut d,mut f,mut p)=fixture();
  if operation=="clone"{for node in &mut d.nodes{if let NodeKind::Element{tag:local,attrs,..}=&mut node.kind{if local==tag{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}}
  p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,&format!("var target=document.getElementById('target'),source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=if operation=="clone"{run(&mut d,&mut f,&mut p,"source=document.getElementById(which);");"source.cloneNode(true);"}else{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);var bad=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(bad);");if operation=="import"{"document.importNode(source,true);"}else{"target.appendChild(source);"}};
  run(&mut d,&mut f,&mut p,"var first=source.firstChild,parent=source.parentNode,owner=source.ownerDocument;");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();if operation=="promote"{run(&mut d,&mut f,&mut p,"var caught=false;try{target.appendChild(source);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught)throw 'typed native promotion guard';");}else{let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}"));assert!(e.contains("not implemented")||e.contains("unavailable")||e.contains("support"),"{tag}/{operation}: {e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==parent||source.ownerDocument!==owner||source.firstChild!==first||target.childNodes.length||watch.takeRecords().length||document.getElementById('neighbor').value!=='seed')throw 'guard has no prefix';");
 }}
}
#[test]
fn gauge_lifecycle_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["progress","meter"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.getElementById('target'),source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById(which);");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.max=10;source.value=2;source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.max=10;source.value=2;source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('value');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('value')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('value')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.value!==source.value||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn gauge_lifecycle_captured_child_insertion_revalidates_origin_before_source_changes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',source=doc.createElementNS(html,'progress'),pending=doc.createElementNS(html,'meter'),target=document.getElementById('target');source.max=10;source.value=3;pending.min=-10;pending.max=10;pending.value=5;var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Node.prototype.appendChild;if(saved===Node.prototype.appendChild||saved.call(target,source)!==source||source.ownerDocument!==document||source.parentNode!==target||source.value!==3)throw 'captured native gauge insertion';"#);
 p.set_location(&crate::navigation::address("https://other-gauge-lifecycle.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute("saved.call(target,pending);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);
 p.set_location(&crate::navigation::address("https://gauge-lifecycle.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(pending.ownerDocument!==doc||pending.parentNode!==null||pending.value!==5||target.childNodes.length!==1)throw 'origin refusal retains actual gauge';if(saved.call(target,pending)!==pending||pending.ownerDocument!==document||pending.parentNode!==target||pending.value!==5||pending.optimum!==0)throw 'origin recovery';");
}

#[test]
fn gauge_lifecycle_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["progress","meter"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.getElementById('target'),owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.max=10;source.value=2;source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('value');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('value')!==attr||source.value!==2||source.parentNode!==target)throw 'reserved native gauge connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn gauge_lifecycle_ordinary_admission_retains_unrelated_raw_name_guards(){
 for tag in ["progress","meter"]{let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag:local,attrs,..}=&mut node.kind{if local==tag{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("name".into()),value:DomString::from("seed".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{tag}'),attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));
  for source in [r#"x.setAttribute('name','A\ud800z');"#,r#"attr.value='A\ud800z';"#,r#"attr.nodeValue='A\ud800z';"#,r#"attr.textContent='A\ud800z';"#]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(source);assert!(e.contains("Unpaired")||e.contains("requires")||e.contains("support"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='seed'||x.getAttributeNode('name')!==attr||watch.takeRecords().length)throw 'raw name guard no prefix';");}
  p.begin_job();run(&mut d,&mut f,&mut p,"x.value=3;var records=watch.takeRecords();if(x.value!==3||attr.value!=='seed'||records.length!==1||records[0].attributeName!=='value')throw 'fresh numeric writer after raw guard';");
 }
}
